import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Real Sinistcha evolves from the actual Poltchageist; real Spiritomb and both printed costs are retained. */
public final class GeneratedRuleBatch73Test {
    static final UUID A=CounterScalingTest.A,B=CounterScalingTest.B;
    static final CardDatabase DB=BundledRules.loadCardDefinitions();static final CombatCatalog DATA=BundledCombatData.load();
    static void check(boolean b,String why){CounterScalingTest.check(b,why);}
    static ServerMatch game(String id){var p=DATA.pokemon(id).orElseThrow();var m=CounterScalingTest.game(DB.find(id).orElseThrow(),p,DATA.pokemon("me5_en_006").orElseThrow().abilities().getFirst());m.attachEnergy(A,CounterScalingTest.get(m,A,"energy").instanceId(),m.activePokemonView(A).pokemonId());check(m.activePokemonView(A).topCardId().equals(id),"Actual evolved/card source missing");return m;}
    public static void main(String[] args){printed();for(int n:List.of(5,6,7))spin(n);for(int n:List.of(12,13,14))end(n);System.out.println("GeneratedRuleBatch73Test passed: actual60HP Sinistcha evolved from actual Poltchageist, Colorless1 MatchaSpin6+ whole opponent field, preserved Hide n Sneak; actual60HP Spiritomb Psychic1 SpiritualEnd13+ deferred2-target independent quadrupling, no attack damage, live count thresholds and turn completion");}
    static void printed(){for(String id:List.of("me5_en_006","me5_en_035")){var c=DB.find(id).orElseThrow();var p=DATA.pokemon(id).orElseThrow();boolean tea=id.equals("me5_en_006");check(c.effectSupport()==EffectSupport.SUPPORTED&&c.basicPokemon()!=tea&&c.copyLimit()==4&&c.regulationMark().equals("J")&&p.hitPoints()==60&&p.retreatCost()==1&&p.prizeCards()==1&&p.attacks().size()==1,"Actual metadata changed");var a=p.attacks().getFirst();check(a.baseDamage()==0&&a.energyCost().equals(Map.of(tea?EnergyType.COLORLESS:EnergyType.PSYCHIC,1)),"Actual printed cost/damage changed");AttackProgramRules.validate(a);if(tea)check(p.evolvesFromDefinitionId().equals("me5_en_005")&&p.evolvesFromName().equals("Poltchageist")&&p.pokemonType()==EnergyType.GRASS&&p.weaknessType()==EnergyType.FIRE&&p.abilities().size()==1&&p.abilities().getFirst().id().equals("hide-n-sneak"),"Tea evolution/Ability changed");else check(p.evolvesFromDefinitionId()==null&&p.pokemonType()==EnergyType.PSYCHIC&&p.weaknessType()==EnergyType.DARKNESS&&p.resistanceType()==EnergyType.FIGHTING&&p.resistanceAmount()==30&&p.abilities().isEmpty(),"Spiritomb metadata changed");}}
    static void spin(int n){var m=game("me5_en_006");CounterScalingTest.fill(m,n);m.attack(A,"matcha-spin");int counters=n>=6?40:0;check(m.activePokemonView(B).damage()==counters&&m.benchPokemonView(B).getFirst().damage()==counters&&m.activePokemonView(A).damage()==0&&m.lastAttack().finalDamage()==0&&m.currentPlayer().equals(B)&&!m.hasPendingPokemonSelection(),"Actual group counters wrong");}
    static void end(int n){var m=game("me5_en_035");CounterScalingTest.fill(m,n);UUID a=m.activePokemonView(B).pokemonId(),b=m.benchPokemonView(B).getFirst().pokemonId();m.placeDamageCountersByEffect(A,B,a,2);m.placeDamageCountersByEffect(A,B,b,1);m.attack(A,"spiritual-end");if(n>=13){check(m.hasPendingPokemonSelection()&&m.lastAttack().finalDamage()==0,"Actual target continuation missing");CounterScalingTest.choose(m,a);check(CounterScalingTest.damage(m,a)==20,"First selection already placed counters");CounterScalingTest.choose(m,b);}check(CounterScalingTest.damage(m,a)==(n>=13?80:20)&&CounterScalingTest.damage(m,b)==(n>=13?40:10)&&m.lastAttack().finalDamage()==0&&m.currentPlayer().equals(B),"Actual each-target quadrupling/threshold wrong");}
}
